    @MainActor private static var cache: [String: NSImage] = [:]

    /// Шаблонное изображение 24×24: цвет задаёт `foregroundStyle`.
    @MainActor static func image(_ name: String) -> NSImage? {
        if let cached = cache[name] { return cached }
        guard let inner = paths[name] else { return nil }
        let svg = #"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24">"# + inner + "</svg>"
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.isTemplate = true
        cache[name] = image
        return image
    }
}
